<script setup lang="ts">import{nextTick,ref,watch}from"vue";import{titleRepository}from"@/domain/repositories";import{editionTypeRepository,libraryCopyRepository,physicalFormatRepository}from"@/domain/library/repository";import{createLibraryCopyForm,hasLibraryCopyErrors,validateLibraryCopyForm,type LibraryCopyErrors}from"@/domain/library/validation";import type{EditionTypeRecord,LibraryCopyRecord,PhysicalFormatRecord}from"@/domain/library/records";import type{NamedRecord,TitleRecord}from"@/types/records";import{PocketBaseRepository}from"@/infrastructure/pocketbase/repository";const peopleRepository=new PocketBaseRepository<NamedRecord>("pessoas");const props=defineProps<{open:boolean;copy:LibraryCopyRecord|null}>();const emit=defineEmits<{close:[];saved:[LibraryCopyRecord]}>();const form=ref(createLibraryCopyForm()),errors=ref<LibraryCopyErrors>({}),submitError=ref(""),saving=ref(false),query=ref(""),results=ref<TitleRecord[]>([]),formats=ref<PhysicalFormatRecord[]>([]),editions=ref<EditionTypeRecord[]>([]),people=ref<NamedRecord[]>([]),first=ref<HTMLInputElement|null>(null);let timer:ReturnType<typeof setTimeout>|undefined;watch(()=>[props.open,props.copy]as const,async([open,copy])=>{if(!open)return;form.value=createLibraryCopyForm(copy||undefined);errors.value={};submitError.value="";query.value=copy?.expand?.titulo?.titulo||"";results.value=[];const[f,e,p]=await Promise.all([physicalFormatRepository.list({page:1,perPage:500,filter:"ativo = true",sort:"categoria,ordem,nome"}),editionTypeRepository.list({page:1,perPage:200,filter:"ativo = true",sort:"categoria,ordem,nome"}),peopleRepository.list({page:1,perPage:500,filter:"ativo = true",sort:"nome"})]);formats.value=f.items;editions.value=e.items;people.value=p.items;await nextTick();first.value?.focus()},{immediate:true});watch(query,value=>{if(timer)clearTimeout(timer);if(value.trim().length<2){results.value=[];return}timer=setTimeout(async()=>{const slash=String.fromCharCode(92),escaped=value.trim().split(slash).join(slash+slash).split('"').join(slash+'"');results.value=(await titleRepository.list({page:1,perPage:20,filter:`apagado = false && (titulo ~ "${escaped}" || titulo_original ~ "${escaped}")`,sort:"titulo"})).items},300)});function select(title:TitleRecord){form.value.titulo=title.id;query.value=`${title.titulo}${title.ano?` (${title.ano})`:""}`;results.value=[]}async function save(){errors.value=validateLibraryCopyForm(form.value);if(hasLibraryCopyErrors(errors.value))return;saving.value=true;try{const payload={titulo:form.value.titulo,formato:form.value.formato,tipo_edicao:form.value.tipo_edicao,numero_copia:form.value.numero_copia||1,codigo_barras:form.value.codigo_barras.trim(),codigo_interno:form.value.codigo_interno.trim(),estado_fisico:form.value.estado_fisico.trim(),regiao:form.value.regiao.trim(),localizacao:form.value.localizacao.trim(),selado:form.value.selado,steelbook:form.value.steelbook,notas:form.value.notas.trim()};const saved=props.copy?await libraryCopyRepository.update(props.copy.id,payload):await libraryCopyRepository.create(payload);emit("saved",saved)}catch(c){submitError.value=c instanceof Error?c.message:String(c)}finally{saving.value=false}}</script><template><Teleport to="body"><div v-if="open" class="dialog-backdrop" @click.self="!saving&&emit('close')"><section class="dialog-panel library-copy-edit" role="dialog" aria-modal="true" aria-labelledby="library-copy-title"><form novalidate @submit.prevent="save"><div class="dialog-header"><div><p class="eyebrow">Biblioteca física</p><h2 id="library-copy-title">{{copy?'Editar exemplar':'Novo exemplar'}}</h2></div><button class="icon-button" type="button" aria-label="Fechar" :disabled="saving" @click="emit('close')">×</button></div><div v-if="submitError" class="form-alert form-alert-error" role="alert">{{submitError}}</div><div class="form-grid"><label class="form-field field-wide"><span>Título *</span><input ref="first" v-model.trim="query" type="search" :aria-invalid="errors.titulo?'true':'false'"/><small v-if="errors.titulo" class="field-error">{{errors.titulo}}</small></label><ul v-if="results.length" class="library-title-results field-wide"><li v-for="title in results" :key="title.id"><button type="button" @click="select(title)"><strong>{{title.titulo}}</strong><span>{{title.ano||'—'}}</span></button></li></ul><label class="form-field"><span>Formato</span><select v-model="form.formato"><option value="">Selecionar</option><option v-for="x in formats" :key="x.id" :value="x.id">{{x.nome}}</option></select></label><label class="form-field"><span>Tipo de edição</span><select v-model="form.tipo_edicao"><option value="">Sem tipo</option><option v-for="x in editions" :key="x.id" :value="x.id">{{x.nome}}</option></select></label><label class="form-field"><span>Número da cópia</span><input v-model.number="form.numero_copia" type="number" min="1" step="1"/></label><label class="form-field"><span>Estado físico</span><input v-model="form.estado_fisico" maxlength="100"/></label><label class="form-field"><span>Região</span><input v-model="form.regiao" maxlength="100"/></label><label class="form-field"><span>Localização</span><input v-model="form.localizacao" maxlength="200"/></label><label class="form-field"><span>Código interno</span><input v-model="form.codigo_interno" maxlength="100"/></label><label class="form-field"><span>Código de barras</span><input v-model="form.codigo_barras" maxlength="100"/></label><label class="check-field"><input v-model="form.selado" type="checkbox"/> Selado</label><label class="check-field"><input v-model="form.steelbook" type="checkbox"/> Steelbook</label><p v-if="copy?.emprestado" class="field-warning field-wide" role="status">Este exemplar está emprestado. Usa a ação Gerir empréstimo na Biblioteca.</p><label class="form-field field-wide"><span>Notas</span><textarea v-model="form.notas" rows="4" maxlength="4000"/><small v-if="errors.notas" class="field-error">{{errors.notas}}</small></label></div><div class="form-actions"><button class="button button-secondary" type="button" @click="emit('close')">Cancelar</button><button class="button button-primary" type="submit" :disabled="saving">{{saving?'A guardar…':'Guardar exemplar'}}</button></div></form></section></div></Teleport></template>
